async function run() {
  const chapterId = rawOutputData.chapterId
  console.log(`\n======================================================`)
  console.log(`📥 Direct Phase 2 MindMap Importer for Chapter ID ${chapterId}`)
  console.log(`======================================================\n`)

  const chapter = await prisma.chapter.findUnique({
    where: { id: chapterId },
    select: { id: true, name: true }
  })

  if (!chapter) {
    throw new Error(`Chapter ${chapterId} not found in database!`)
  }

  // 1. Collect and deduplicate all concepts from categories
  const collected = new Set<string>()
  for (const cat of rawOutputData.categories) {
    for (const sub of cat.subCategories) {
      for (const kw of sub.keywords) {
        if (kw && kw.trim()) collected.add(kw.trim())
      }
    }
  }
  for (const kw of rawOutputData.allKeywords) {
    if (kw && kw.trim()) collected.add(kw.trim())
  }
  const deduplicatedKeywords = Array.from(collected).sort()
  console.log(`📊 Found ${rawOutputData.categories.length} Macro-Categories`)
  console.log(`⚡ Total Deduplicated Concepts across subcategories: ${deduplicatedKeywords.length}`)

  // 2. Compute TNAU Syllabus Audit
  const tnauSpine = getTNAUSpine(chapter.name)
  const mustCoverTopics = tnauSpine?.mustCoverTopics || []
  const extractedLower = new Set(deduplicatedKeywords.map(k => k.toLowerCase()))
  const gapTopics = mustCoverTopics.filter(topic => {
    const topicLower = topic.toLowerCase()
    return !Array.from(extractedLower).some(extracted => 
      extracted.includes(topicLower) || topicLower.includes(extracted)
    )
  })

  const totalStandard = mustCoverTopics.length || 1
  const coveredCount = Math.max(0, mustCoverTopics.length - gapTopics.length)
  const scorePercent = Math.round((coveredCount / totalStandard) * 100)

  const syllabusAudit = {
    scorePercent: Math.min(100, Math.max(0, scorePercent)),
    totalBenchmarkTopics: mustCoverTopics.length,
    coveredTopicsCount: coveredCount,
    gapTopics,
    tnauSourceUrl: tnauSpine?.sourceUrl
  }

  console.log(`🎓 TNAU Benchmark Audit Score: ${syllabusAudit.scorePercent}% (${coveredCount}/${mustCoverTopics.length} benchmark topics covered)`)

  const finalTreeData: ChapterMindMapTree = {
    chapterId,
    chapterName: chapter.name,
    categories: rawOutputData.categories,
    crossBranchEdges: rawOutputData.crossBranchEdges,
    allKeywords: deduplicatedKeywords,
    syllabusAudit
  }

  // 3. Upsert into database
  console.log(`💾 Saving into ChapterMindMap database table...`)
  const record = await prisma.chapterMindMap.upsert({
    where: { chapterId },
    create: {
      chapterId,
      treeData: finalTreeData as any,
      rawKeywords: deduplicatedKeywords,
      lastSyncAt: new Date()
    },
    update: {
      treeData: finalTreeData as any,
      rawKeywords: deduplicatedKeywords,
      lastSyncAt: new Date()
    }
  })

  console.log(`✅ SUCCESS! Phase 2 Master MindMap for Chapter "${chapter.name}" (ID ${chapterId}) is now saved in the database.`)
  console.log(`Record ID: ${record.id}, Last Synchronized: ${record.lastSyncAt.toISOString()}`)
  console.log(`\nYou can now refresh the Admin Concepts page directly without running the AI job again!`)
}

run()
  .catch((err) => {
    console.error('❌ Error during import:', err)
    process.exit(1)
  })
  .finally(async () => {
    await prisma.$disconnect()
  })
